<?php
namespace App\Exports;use App\Models\AttendanceEvent;use Maatwebsite\Excel\Concerns\{FromCollection,WithHeadings,WithMapping};class AttendanceExport implements FromCollection,WithHeadings,WithMapping{public function __construct(private AttendanceEvent $event){}public function collection(){return$this->event->participants()->with('record')->get();}public function headings():array{return['Participante','Cargo o rol','Tipo','Fecha','Hora','Método','Estado'];}public function map($p):array{return[$p->name_snapshot,$p->role_snapshot,$p->participant_type,$p->record?->confirmed_at?->format('d/m/Y'),$p->record?->confirmed_at?->format('H:i'),$p->record?->verification_method,$p->record?->status??'pending'];}}
